import requests
import logging
import re

DISABLE_WARNINGS = True
log = logging.getLogger(__name__)

if DISABLE_WARNINGS:
    from requests.packages.urllib3.exceptions import InsecureRequestWarning

    requests.packages.urllib3.disable_warnings(InsecureRequestWarning)


class UrlOperations(object):
    @staticmethod
    def join_urls(url1, url2):
        return '/'.join(s.lstrip('/') for s in [url1, url2])

    @staticmethod
    def process_url(url, port=None):
        url = url.rstrip('/')
        if not url.startswith('http'):
            log.debug("No protocol defined by user, https will be used.")
            url = "https://" + url
        if port is not None:
            url = '{0}:{1}'.format(url, port)
        return url


class Session(requests.Session):
    """Class responsible for authorization and creating session"""
    CSRF_IGNORED_METHODS = ['GET', 'HEAD', 'OPTIONS']
    DEFAULT_HEADER = {'content-type': 'application/json'}

    def send_request(self, url, method='GET', verify=False, headers=None, add_headers=True,
                     **kwargs):
        # TODO: split his method, add more methods such as send_json/request_json
        if add_headers and headers is None and method in ['POST', 'PUT']:
            headers = self.DEFAULT_HEADER
        elif headers is None:
            headers = {}

        if self._csrf_token is not None and method not in self.CSRF_IGNORED_METHODS:
            csrf_header = {'csrf-token': self._csrf_token}
            headers.update(csrf_header)

        request_method = getattr(self, method.lower())
        response = request_method(UrlOperations.join_urls(self.url, url),
                                  verify=verify,
                                  headers=headers, **kwargs)

        response.raise_for_status()
        return response

    def __init__(self, base_url, username, password, port=None, timeout=30):
        super(Session, self).__init__()

        self.url = UrlOperations.process_url(url=base_url, port=port)

        self._AUTH_ENDPOINT = 'login'
        self._CSRF_ENDPOINT = 'login.html'
        self._CREDENTIALS = dict(username=username, password=password)

        self.authenticated = False

        self._csrf_token = None
        self._authenticate(timeout=timeout)

    @property
    def username(self):
        return self._CREDENTIALS['username']

    def _get_csrf_secret(self):
        return self.cookies.get('_csrf', None)

    def _set_csrf_token(self, timeout=30):
        resp = self.send_request(self._CSRF_ENDPOINT, method='GET',
                                 data=self._CREDENTIALS,
                                 verify=False, add_headers=False, timeout=timeout)

        csrf_token_matcher = re.search("name=\"csrf-token\".*?content=\"(.*?)\".*?>", str(resp.content))
        if not csrf_token_matcher:
            return None

        self._csrf_token = csrf_token_matcher.group(1)

    def _authenticate(self, timeout=30):
        auth_response = self.send_request(self._AUTH_ENDPOINT, method='POST',
                                          data=self._CREDENTIALS,
                                          verify=False, add_headers=False, timeout=timeout)

        self.authenticated = auth_response.ok

        csrf_enabled = self._get_csrf_secret() or False

        if self.authenticated and csrf_enabled:
            self._set_csrf_token()

    def teardown(self, timeout=10):
        self.send_request('logout', method='GET', verify=False,
                          add_headers=False, timeout=timeout)

    def __del__(self):
        if not self.authenticated:
            return
        try:
            self.teardown()
        except Exception:
            pass


class AnonymousSession(requests.Session):
    """ This class should be used if no authorization is required. """
    DEFAULT_HEADER = {'content-type': 'application/json'}

    def __init__(self, base_url, port=None):
        super(AnonymousSession, self).__init__()
        self.url = UrlOperations.process_url(url=base_url, port=port)

    def teardown(self, timeout=10):
        pass

    def send_request(self, url, method='GET', verify=False, headers=None,
                     add_headers=True,
                     **kwargs):
        # TODO: split his method, add more methods such as send_json/request_json
        if add_headers and headers is None and method in ['POST', 'PUT']:
            headers = self.DEFAULT_HEADER
        request_method = getattr(self, method.lower())

        response = request_method(UrlOperations.join_urls(self.url, url),
                                  verify=verify,
                                  headers=headers, **kwargs)
        response.raise_for_status()
        return response
